{
  "summary": "ENOSPC errors on kafka-02 /var are likely due to the root filesystem filling up, commonly from Kafka GC logs.",
  "likely_cause": "/var partition full, often caused by unrotated Kafka GC logs.",
  "confidence": "high",
  "claims": [
    {
      "text": "The first step is to identify which filesystem is full, as ENOSPC can refer to either the data volume or the root disk.",
      "evidence_ids": ["INC-0070#3"],
      "quote": "ENOSPC says a write had nowhere to go on the filesystem it was aimed at. ... first job is to find out which is full."
    },
    {
      "text": "On kafka-02 the /var filesystem has filled up from GC logs.",
      "evidence_ids": ["RB-008#2"],
      "quote": "kafka-02.prod.internal `/var` full from GC logs"
    },
    {
      "text": "GC logs live in /var/log/kafka and should be rotated; they are not part of the data directory.",
      "evidence_ids": ["RB-008#2"],
      "quote": "Broker GC logs live in `/var/log/kafka`. Rotate them; don't touch `/data/kafka`"
    }
  ],
  "next_checks": [
    "Run `df -h /var` and `df -h /data/kafka` on kafka-02 to see which mount is at capacity.",
    "Inspect /var/log/kafka for large or unrotated GC log files.",
    "Verify logrotate configuration for /var/log/kafka and ensure it is active.",
    "If /var is full, clean or rotate GC logs and consider expanding the root volume."
  ]
}
